"""Reviewed remaining apple/prune group; explicit recipes, no title-based promotion."""
import json,pathlib,sqlite3,copy
root=pathlib.Path(__file__).parent
db=sqlite3.connect(root.parent.parent/'outputs/SavorShelf-Content-Repairs/grouped-work.sqlite3')
rows=json.loads((root.parent.parent/'outputs/SavorShelf-Content-Repairs/apple-prune-candidates.json').read_text(encoding='utf-8'))
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
merges={7:6,9:8};newids=[]
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def A(n):return I('apples',n,'','medium firm apples, about 180 g each','Use another firm apple of similar size; cooking time and sweetness differ.')
def W(n,k='water'):return I(k,n,'ml','drinking water','Use the same volume of unsweetened apple juice for a sweeter fruit dish.')
def S(n):return I('sugar',n,'g','granulated sugar','Reduce to taste; this is not a shelf-stable preserve.')
def L(n):return I('lemon',n,'ml','lemon juice','Use the same volume of lime juice for a different citrus flavor.')
def Z(n):return I('zest',n,'g','finely grated lemon zest, yellow part only','Use the same weight of orange zest, or omit.')
def C(n=.5):return I('cinnamon',n,'tsp','ground cinnamon','Use half as much ground allspice for a different flavor, or omit.')
def B(n):return I('butter',n,'g','unsalted butter','Use the same weight of a block-style dairy-free alternative.')
def cream(n):return I('cream',n,'ml','heavy cream','Use the same volume of plant-based cream suitable for the stated use.')
def add(n,title,servings,minutes,desc,items,steps,notes,category='Desserts'):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category=category,servings=servings,yieldUnit='servings',minutes=minutes,totalMinutes=minutes,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T16:00:00Z',source=s['recipe']['source']+' SavorShelf measured adaptation.',notes=notes+' Missing quantities, yields and timings are disclosed modern estimates, not recovered historical measures. Not kitchen-tested. Scaling changes quantities, not time or temperature. Refrigerate in shallow containers within 2 hours at 4°C (40°F) or colder; freeze for longer storage. Not a canning recipe.')
 r.pop('variants',None);r['sourceAliases']=[rows[o]['id'] for o,d in merges.items() if d==n]
 for o,d in merges.items():
  if d==n:r['source']+=' Equivalent source retained: '+src(o)['recipe']['source']
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def poach(n,title,fruit,sug,wat,desc,extra=(),shape='halves',notes='',cold=False):
 prep='Rinse {{apples}}, peel and remove every core and seed. '+('Keep the apples whole.' if shape=='whole' else 'Cut into '+shape+'.')
 if shape=='skin-on halves':prep='Rinse {{apples}}, halve without peeling, and scoop out all cores and seeds. Prick the skins with a fork.'
 flavor=''.join(', {{'+i['key']+'}}' for i in extra)
 steps=[prep,'In a snug pan, heat {{water}} with {{sugar}}'+flavor+', stirring until the sugar dissolves. Add the apples in one layer, working in batches if needed.','Cover and simmer gently, turning carefully halfway through, until a knife enters easily but the fruit holds its shape: about '+('20–35' if shape=='whole' else '10–20')+' minutes. Baste frequently; add a little water if the liquid becomes too thick before the fruit softens.','Lift the apples onto a serving dish. Simmer the liquid uncovered for 3–8 minutes until lightly syrupy, then spoon it over the fruit.']
 steps+=['Cool briefly, then refrigerate within 2 hours. Chill for at least 1 hour before serving.'] if cold else ['Rest for 5 minutes and serve warm, or refrigerate promptly for serving cold.']
 return add(n,title,fruit,125 if cold else 50,desc,[A(fruit),S(sug),W(wat),*extra],steps,notes)
